/* js/data.js — loads the app's static data files with fetch() before init()
 * renders anything (js/main.js awaits OSR.loadData()).
 *
 * The app runs over http(s) only (GitHub Pages, or any static server), so
 * the data lives in data/ as plain JSON/text, never as <script> copies:
 *   - data/monsters.json, data/spells.json, data/tables.json — GENERATED by
 *     the converters in scripts/;
 *   - data/seed-<system>.json — the hand-maintained seed for each system:
 *     { system, version, compendium: [...], monsters?: [...] };
 *   - data/*.txt — the example characters (pregens).
 *
 * Result, on OSR.data:
 *   monsters  the OSR (Shadowdark/OSE) bestiary
 *   tables    the random tables (Tables tab)
 *   seeds     { osr, brp, sl } → { version, compendium, monsters }; the OSR
 *             Compendium seed is the gear from data/seed-osr.json plus every
 *             spell from data/spells.json whose name is not already there
 *   pregens   [{ file, text }] in PREGEN_FILES order
 */
(function (OSR) {
  'use strict';

  const PREGEN_FILES = [
    'data/garrick-wwn.txt', 'data/gulzund-blize-shadowdark.txt',
    'data/kevin-johnson-ua3e.txt', 'data/lucinda-adams-ua3e.txt',
    'data/dee-okafor-sl.txt', 'data/miriam-castell-sl.txt',
    'data/vivian-sato-sl.txt', 'data/ray-kowalczyk-sl.txt'
  ];

  OSR.data = { monsters: [], tables: [], seeds: {}, pregens: [] };

  async function get(url, as) {
    let res;
    try { res = await fetch(url); } catch (e) { throw new Error(url + ': ' + e.message); }
    if (!res.ok) throw new Error(url + ': HTTP ' + res.status);
    return as === 'text' ? res.text() : res.json();
  }

  function withSpells(gear, spells) {
    const have = new Set(gear.map(d => d.name.trim().toLowerCase()));
    const out = gear.slice();
    spells.forEach(s => {
      if (!s || !s.name || !s.body || have.has(String(s.name).trim().toLowerCase())) return;
      have.add(String(s.name).trim().toLowerCase());
      out.push({ name: String(s.name), category: s.category || 'Spells', body: String(s.body) });
    });
    return out;
  }

  // Rejects with every failed file's name, so the error state can list them.
  async function loadData() {
    const jobs = {
      monsters: get('data/monsters.json'), spells: get('data/spells.json'), tables: get('data/tables.json'),
      osr: get('data/seed-osr.json'), brp: get('data/seed-brp.json'), sl: get('data/seed-sl.json'),
      pregens: Promise.all(PREGEN_FILES.map(f => get(f, 'text')))
    };
    const keys = Object.keys(jobs);
    const settled = await Promise.allSettled(keys.map(k => jobs[k]));
    const failed = settled.filter(s => s.status === 'rejected').map(s => s.reason.message);
    if (failed.length) throw new Error('Could not load ' + failed.join('; '));
    const r = {};
    keys.forEach((k, i) => { r[k] = settled[i].value; });
    const seed = (s, extra) => ({ version: Number(s.version) || 1, compendium: s.compendium || [], monsters: s.monsters || [], ...extra });
    OSR.data = {
      monsters: r.monsters,
      tables: r.tables,
      seeds: {
        osr: seed(r.osr, { compendium: withSpells(r.osr.compendium || [], r.spells), monsters: r.monsters }),
        brp: seed(r.brp),
        sl: seed(r.sl)
      },
      pregens: PREGEN_FILES.map((file, i) => ({ file, text: r.pregens[i] }))
    };
    return OSR.data;
  }

  Object.assign(OSR, { PREGEN_FILES, loadData });
})(window.OSR = window.OSR || {});
